from PIL import Image
import numpy as np, os, itertools

files = sorted(f for f in os.listdir('textures') if f.lower().endswith('.png'))
data = {}
for f in files:
    img = np.asarray(Image.open('textures/'+f).convert('RGB'))
    data[f] = img

# signature: mean of R,B per 16x16 block (robust to small differences)
def sig(img):
    h, w, _ = img.shape
    b = 16
    n = min(h//b, w//b)
    blocks = []
    for i in range(n):
        for j in range(n):
            blk = img[i*b:(i+1)*b, j*b:(j+1)*b]
            blocks.append((blk[:,:,0].mean().round(1), blk[:,:,1].mean().round(1), blk[:,:,2].mean().round(1)))
    return tuple(blocks)

sigs = {f: sig(data[f]) for f in files}

# find pairs with identical R,B signatures and mirrored G
for f1, f2 in itertools.combinations(files, 2):
    s1, s2 = sigs[f1], sigs[f2]
    if all(a[0]==b[0] and a[2]==b[2] for a,b in zip(s1,s2)):
        print("SAME R,B:", f1, "<->", f2)

# also: near-identical R,B (within tolerance)
print("\n--- near matches (R,B diff < 0.5 per block mean) ---")
for f1, f2 in itertools.combinations(files, 2):
    s1, s2 = sigs[f1], sigs[f2]
    d = np.mean([abs(a[0]-b[0])+abs(a[2]-b[2]) for a,b in zip(s1,s2)])
    if d < 0.5:
        print(f"near: {f1} <-> {f2}  dRdB={d:.3f}")
